(function(r){'use strict';const O=r.NeonCombat.AIObserver288;let box,g,last=0;function refresh(force=false){if(!box?.open||!g)return;const now=performance.now();if(!force&&now-last<200)return;last=now;const select=box.querySelector('select'),key=g.enemies.map(e=>e.id).join(',');if(select.dataset.roster!==key){const old=select.value;select.replaceChildren();for(const e of g.enemies){const o=document.createElement('option');o.value=e.id;o.textContent=(e.name||e.type)+' #'+e.id;select.append(o)}select.dataset.roster=key;if(g.enemies.some(e=>String(e.id)===old))select.value=old}const e=g.enemies.find(e=>String(e.id)===select.value);if(e){const {decisionContext,denied,director,candidateWeights,nativeReasonFields,controllerData,...live}=O.snapshot(g,e);box.querySelector('[data-current288]').textContent=JSON.stringify({...live,director:{primary:director.primary,secondary:director.secondary,roles:director.roles}},null,2);box.querySelector('[data-decision288]').textContent=JSON.stringify(decisionContext,null,2);box.querySelector('[data-native-history288]').textContent=JSON.stringify({denial:denied,lastDirectorRequest:director.latestRequest,controllerData,candidateWeights,nativeReasonFields,note:'Native fields may predate the last observed attempt. A granted request is admission, not a move-selection explanation.'},null,2);}else for(const key of ['current288','decision288','native-history288'])box.querySelector('[data-'+key+']').textContent='No active enemy in this section.';box.querySelector('[data-source288]').textContent=e?JSON.stringify(O.controller(e),null,2):'N/A';const rows=e?O.events(g,e.id).slice(-80):[];box.querySelector('[data-history288]').textContent=rows.length?rows.map(q=>JSON.stringify(q)).join('\n\n'):'No recorded decisions. Enable recording and run or step the simulation.';box.querySelector('[data-record288]').checked=O.enabled(g)}
function mount(host,game){g=game;if(!box){box=document.createElement('details');box.dataset.aiInspector288='';box.innerHTML='<summary>Enemy AI logic &amp; decision history</summary><p>Select any active enemy. Use Practice opponent to test another type. Reasons come from native controller data; unexposed scores or random-roll reasons are N/A.</p><label><input data-record288 type="checkbox"> Record AI decisions</label> <label>AI enemy <select aria-label="AI enemy"></select></label> <button type="button" data-clear288>Clear AI history</button> <button type="button" data-export288>Export AI history</button><h4>Live actor state</h4><pre data-current288 style="max-height:24vh;overflow:auto"></pre><h4>Last observed attempt and action correlation</h4><p>Recording covers calls reaching the observer. Later outer guards may reject without a record; missing reasons remain N/A. Last observed does not mean current.</p><pre data-decision288 style="max-height:28vh;overflow:auto"></pre><h4>Historical native denial and last Director request</h4><pre data-native-history288 style="max-height:24vh;overflow:auto"></pre><details><summary>View native selection code</summary><pre data-source288 style="max-height:30vh;overflow:auto;white-space:pre-wrap"></pre></details><p>Frame numbers use native world time ×60; the playback-session counter may start later.</p><h4>Recorded choices and rejections</h4><pre data-history288 style="max-height:30vh;overflow:auto;white-space:pre-wrap"></pre>';box.ontoggle=()=>refresh(true);box.querySelector('[data-record288]').onchange=e=>{O.enable(g,e.target.checked);refresh(true)};box.querySelector('select').onchange=()=>refresh(true);box.querySelector('[data-clear288]').onclick=()=>{O.clear(g);refresh(true)};box.querySelector('[data-export288]').onclick=()=>{const b=new Blob([JSON.stringify({kind:'actual-native-AI-observations',events:O.events(g)},null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='urban-fracture-AI-history.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};}if(box.parentNode!==host)host.prepend(box);refresh()}r.AIInspector288={mount,refresh};})(globalThis);
